CREATE TABLE `clientes` (`id_cliente` INT NOT NULL AUTO_INCREMENT, `nombre` VARCHAR(110) NOT NULL COMMENT 'Nombre completo', `correo` VARCHAR(160) NOT NULL, `ciudad` VARCHAR(90), `fecha_registro` DATE NOT NULL, `activo` TINYINT(1) NOT NULL DEFAULT 1, PRIMARY KEY (`id_cliente`)) ENGINE=InnoDB COMMENT='Personas registradas';
CREATE TABLE `categorias` (`id_categoria` INT NOT NULL AUTO_INCREMENT, `nombre` VARCHAR(100) NOT NULL, `descripcion` VARCHAR(180), PRIMARY KEY (`id_categoria`)) ENGINE=InnoDB COMMENT='Clasificación de recursos';
CREATE TABLE `productos` (`id_producto` INT NOT NULL AUTO_INCREMENT, `id_categoria` INT NOT NULL, `nombre` VARCHAR(130) NOT NULL, `precio` DECIMAL(11,2) NOT NULL, `existencias` INT NOT NULL DEFAULT 0, `activo` TINYINT(1) NOT NULL DEFAULT 1, PRIMARY KEY (`id_producto`), KEY `idx_recurso_categoria` (`id_categoria`), CONSTRAINT `fk_recurso_categoria` FOREIGN KEY (`id_categoria`) REFERENCES `categorias` (`id_categoria`)) ENGINE=InnoDB COMMENT='Recursos o artículos del catálogo';
CREATE TABLE `sucursales` (`id_sucursal` INT NOT NULL AUTO_INCREMENT, `nombre` VARCHAR(110) NOT NULL, `ciudad` VARCHAR(90) NOT NULL, `fecha_apertura` DATE, PRIMARY KEY (`id_sucursal`)) ENGINE=InnoDB COMMENT='Ubicaciones operativas';
CREATE TABLE `vendedores` (`id_vendedor` INT NOT NULL AUTO_INCREMENT, `id_sucursal` INT NOT NULL, `nombre` VARCHAR(110) NOT NULL, `salario` DECIMAL(11,2), `fecha_ingreso` DATE, `activo` TINYINT(1) NOT NULL DEFAULT 1, PRIMARY KEY (`id_vendedor`), KEY `idx_empleado_sede` (`id_sucursal`), CONSTRAINT `fk_empleado_sede` FOREIGN KEY (`id_sucursal`) REFERENCES `sucursales` (`id_sucursal`)) ENGINE=InnoDB COMMENT='Personal';
CREATE TABLE `pedidos` (`id_pedido` INT NOT NULL AUTO_INCREMENT, `id_cliente` INT NOT NULL, `id_vendedor` INT NOT NULL, `id_sucursal` INT NOT NULL, `fecha` DATE NOT NULL, `estado` VARCHAR(25) NOT NULL, `total` DECIMAL(12,2) NOT NULL, `comentario` VARCHAR(180), PRIMARY KEY (`id_pedido`), KEY `idx_operacion_persona` (`id_cliente`), KEY `idx_operacion_empleado` (`id_vendedor`), KEY `idx_operacion_sede` (`id_sucursal`), CONSTRAINT `fk_operacion_persona` FOREIGN KEY (`id_cliente`) REFERENCES `clientes` (`id_cliente`), CONSTRAINT `fk_operacion_empleado` FOREIGN KEY (`id_vendedor`) REFERENCES `vendedores` (`id_vendedor`), CONSTRAINT `fk_operacion_sede` FOREIGN KEY (`id_sucursal`) REFERENCES `sucursales` (`id_sucursal`)) ENGINE=InnoDB COMMENT='Registro principal de operaciones';
CREATE TABLE `lineas_pedido` (`id_linea_pedido` INT NOT NULL AUTO_INCREMENT, `id_pedido` INT NOT NULL, `id_producto` INT NOT NULL, `cantidad` INT NOT NULL, `precio_unitario` DECIMAL(11,2) NOT NULL, `descuento` DECIMAL(10,2) NOT NULL DEFAULT 0, PRIMARY KEY (`id_linea_pedido`), KEY `idx_detalle_operacion` (`id_pedido`), KEY `idx_detalle_recurso` (`id_producto`), CONSTRAINT `fk_detalle_operacion` FOREIGN KEY (`id_pedido`) REFERENCES `pedidos` (`id_pedido`), CONSTRAINT `fk_detalle_recurso` FOREIGN KEY (`id_producto`) REFERENCES `productos` (`id_producto`)) ENGINE=InnoDB COMMENT='Detalle de recursos por operación';
CREATE TABLE `pagos_pedido` (`id_pago_pedido` INT NOT NULL AUTO_INCREMENT, `id_pedido` INT NOT NULL, `fecha_pago` DATE NOT NULL, `monto` DECIMAL(12,2) NOT NULL, `metodo` VARCHAR(25) NOT NULL, `confirmado` TINYINT(1) NOT NULL DEFAULT 1, PRIMARY KEY (`id_pago_pedido`), KEY `idx_pago_operacion` (`id_pedido`), CONSTRAINT `fk_pago_operacion` FOREIGN KEY (`id_pedido`) REFERENCES `pedidos` (`id_pedido`)) ENGINE=InnoDB COMMENT='Movimientos de cobro';
CREATE TABLE `incidencias_pedido` (`id_incidencia_pedido` INT NOT NULL AUTO_INCREMENT, `id_pedido` INT NOT NULL, `fecha_evento` DATE NOT NULL, `tipo` VARCHAR(50) NOT NULL, `descripcion` VARCHAR(220), `puntuacion` INT, PRIMARY KEY (`id_incidencia_pedido`), KEY `idx_evento_operacion` (`id_pedido`), CONSTRAINT `fk_evento_operacion` FOREIGN KEY (`id_pedido`) REFERENCES `pedidos` (`id_pedido`)) ENGINE=InnoDB COMMENT='Eventos de seguimiento asociados a una operación';
